var ANY_ZONE_DAY_TEXT = `check_sky_fact takes no time zone, so a date is read as that day in every UTC offset in use today, from \u2212${ANY_ZONE_DAY.endHoursAfterUtcMidnight - 24}:00 to +${ANY_ZONE_DAY.startHoursBeforeUtcMidnight}:00, at once: from ${ANY_ZONE_DAY.startHoursBeforeUtcMidnight} hours before its midnight UTC to ${ANY_ZONE_DAY.endHoursAfterUtcMidnight} hours after. depends means the answer turns on the time of day or on the offset.`;
var POSITIONS_INPUT = z.strictObject({
  instants: z.array(z.string().max(INSTANT_CHARS)).min(1).max(BUDGETS["positions.instants"]).describe(`One to ${BUDGETS["positions.instants"]} instants, each in ${instantForm}`),
  bodies: z.array(z.enum(POSITION_BODIES)).min(1).optional().describe("Which rows to return, each named once; all twelve when omitted.")
});
var EVENTS_INPUT = z.strictObject({
  from: z.string().max(INSTANT_CHARS).describe(`The start of the window, which is excluded, in ${instantForm}`),
  to: z.string().max(INSTANT_CHARS).describe(`The end of the window, which is included: later than from and at most ${BUDGETS["events.windowDays"]} days after it, in ${instantForm}`),
  bodies: z.array(z.enum(EVENT_BODIES)).min(1).optional().describe("Which bodies to search, each named once; all ten when omitted. Only Mercury to Pluto station: the Sun and the Moon never move backward."),
  kinds: z.array(z.enum(EVENT_KINDS)).min(1).optional().describe("ingress: a body entering a sign. station: a planet turning retrograde or direct. lunation: a new or full moon, whichever bodies are named. Each named once; all three when omitted.")
});
var ASPECT_ORBS = ASPECTS.map(({ type, angle, orb, luminaryOrb }) => `${type} ${angle}\xB0 within ${orb}\xB0 (${luminaryOrb}\xB0 with the Sun or the Moon)`).join(", ");
var SKY_FACT_INPUT = z.strictObject({
  kind: z.enum(SKY_FACT_KINDS).describe("sign: is the body in the sign? retrograde: is the body retrograde? ingress: does the body enter the sign on the date? phase: does the Moon reach the phase on the date? aspect: are the body and the other body in the aspect?"),
  body: z.enum(EVENT_BODIES).optional().describe("For sign, retrograde, ingress and aspect."),
  other: z.enum(EVENT_BODIES).optional().describe("For aspect: the second body, not the same as body."),
  aspect: z.enum(ASPECT_TYPES).optional().describe(`For aspect, within the orbs a chart's aspects use: ${ASPECT_ORBS}.`),
  sign: z.enum(SIGN_SLUGS2).optional().describe("For sign and ingress, in lowercase."),
  phase: z.enum(PHASE_NAMES).optional().describe("For phase."),
  instant: z.string().max(INSTANT_CHARS).optional().describe(`For sign, retrograde and aspect: the moment to check, in ${instantForm} Give instant or date, not both.`),
  date: z.string().max(DATE_CHARS).optional().describe(`YYYY-MM-DD, from ${EPOCH.firstYear}-01-01 to ${EPOCH.lastYear}-12-31. Needed for ingress and phase; for sign, retrograde and aspect, the alternative to instant. ${ANY_ZONE_DAY_TEXT}`)
});

