function solarHouse(planetSign, sunSign) {
  const p = SIGN_SLUGS3.indexOf(planetSign);
  const s = SIGN_SLUGS3.indexOf(sunSign);
  return (p - s + 12) % 12 + 1;
}
function wholeSignHouseFromAsc(planetSign, ascSign) {
  const p = SIGN_SLUGS3.indexOf(planetSign);
  const a = SIGN_SLUGS3.indexOf(ascSign);
  return (p - a + 12) % 12 + 1;
}
