    signName: signName6,
    period: args.period,
    focus,
    from,
    to,
    label,
    zone: zone7,
    zoneSource,
    reading,
    focusReadings,
    sky,
    message: notes.length ? notes.join(" ") : null,
    available: { months: servedMonths, years },
    pageUrl,
    disclosure: HOROSCOPE_PERIOD_DISCLOSURE
