// src/ai-tools/sanitize.ts
function sanitizeProtocolMessage(message, refusal) {
  if (message.error) message.error = {
    code: message.error.code,
    message: "The MCP request does not match a supported operation or schema.",
    ...message.error.code === -32015 ? { data: { reason: message.error.data?.reason === "timeout" ? "timeout" : "challenge_failed" } } : {}
  };
  else if (message.result?.isError && !message.result?.structuredContent?.schema && message.result.content?.some((item) => item.type === "text" && item.text.startsWith("Input validation error:"))) {
    if (refusal) {
      message.result.structuredContent = refusal;
      message.result.content = [{ type: "text", text: JSON.stringify(refusal) }];
    } else message.result.content = [{ type: "text", text: "The tool arguments do not match the supported schema." }];
  }
  return message;
}

// src/ai-tools/local.ts
function respondWithoutLifetimeBoundary(run2) {
  try {
    const result = run2();
    return result.ok ? { content: [{ type: "text", text: JSON.stringify(result.value) }], structuredContent: result.value } : { isError: true, content: [{ type: "text", text: result.refusal }] };
  } catch {
    return { isError: true, content: [{ type: "text", text: "The local calculation could not complete. No partial result is returned." }] };
  }
}
function build() {
  const server = createAiServer({});
  server.registerTool("get_local_chart_capabilities", { description: `Local natal and comparison conventions, bounds and privacy. ${PRIVACY.assistant}`, inputSchema: CAPABILITIES_INPUT, annotations: READ_ONLY }, () => respond(() => {
    const outcome = describeLocalChartCapabilities();
    return outcome.ok ? { ok: true, value: { ...outcome.value, adapter: { name: "zodiacs-developer", version: AI_VERSION, releaseStatus: "unpublished-candidate", transport: "stdio" } } } : outcome;
  }));
  server.registerTool("calculate_natal_chart", { description: `Calculate one natal chart locally; request output: record for an exportable receipt. Do not invent a birth time or place. ${PRIVACY.assistant}`, inputSchema: NATAL_INPUT, annotations: READ_ONLY }, (args) => respond(() => calculateNatalChart(args)));
  server.registerTool("compare_calculation_records", { description: `Compare two record strings locally. Pass the record field from calculate_natal_chart with output: record. Do not pass paths or URLs. Preserve evidence levels. ${PRIVACY.assistant}`, inputSchema: COMPARE_INPUT, annotations: READ_ONLY }, (args) => respond(() => compareCalculationRecords(args)));
  return server;
}
